<div class="mx-auto max-w-7xl px-4 py-5 sm:px-6 lg:px-8 lg:py-8">
	<header class="relative overflow-hidden rounded-card bg-term px-6 py-10 text-term-ink sm:px-10 sm:py-14 lg:px-14">
