			<div class="border-t border-white/12 pt-6 lg:border-t-0 lg:border-l lg:pt-0 lg:pl-8">
				<label for="docs-search" class="text-small text-white/65">Find a guide</label>
				<div class="relative mt-2"><Icon name="search" size={15} class="pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 text-white/50" /><input id="docs-search" class="field border-white/15 bg-black/20 pl-9 text-white placeholder:text-white/60" type="search" placeholder="Sites, widgets, restore…" bind:value={query} /></div>
				<p class="mt-3 text-small text-white/65">7 runtimes · 18 widget kinds · 3 site modes</p>
