		<main class="min-w-0 space-y-5">
			{#each filtered as section}
				<section id={section.id} class="scroll-mt-5 overflow-hidden rounded-card border border-rule-soft bg-panel">
					<header class="flex items-start gap-3 border-b border-rule-soft bg-paper/40 px-5 py-5 sm:gap-4 sm:px-7">
						<span class="grid size-9 shrink-0 place-items-center rounded-tile border border-rule-soft bg-raised text-action sm:size-11"><Icon name={iconFor(section.id)} size={18} /></span>
						<div class="min-w-0 sm:pt-1"><h2 class="text-section font-semibold">{section.title}</h2><p class="mt-0.5 max-w-measure text-muted">{section.summary}</p></div>
					</header>

					<div class="px-5 py-6 sm:px-7 sm:py-7">
						{#if section.id === 'quickstart'}
							<ol class="max-w-measure divide-y divide-rule-soft">
								{#each section.body as p, i}<li class="flex gap-3 py-4 first:pt-0 last:pb-0"><span class="step-no mt-1">{i + 1}</span><p class="min-w-0 leading-7">{p}</p></li>{/each}
							</ol>
