							<div class="max-w-measure space-y-3 leading-7 break-words">{#each section.body as p}<p>{p}</p>{/each}</div>
						{/if}

						{#if section.id === 'sites'}
							<figure class="mt-6 border-t border-rule-soft pt-5">
								<div class="grid gap-4 sm:grid-cols-[1fr_auto_1fr_auto_1fr] sm:items-start">
									<div><Icon name="discord" size={18} class="text-action" /><strong class="mt-2 block">Bot</strong><span class="text-small text-muted">Publishes validated widgets</span></div>
									<Icon name="chevronRight" size={16} class="mt-0.5 hidden text-muted sm:block" />
									<div><Icon name="pencil" size={18} class="text-action" /><strong class="mt-2 block">Page Studio</strong><span class="text-small text-muted">Composes the public surface</span></div>
									<Icon name="chevronRight" size={16} class="mt-0.5 hidden text-muted sm:block" />
									<div><Icon name="globe" size={18} class="text-action" /><strong class="mt-2 block">Sites origin</strong><span class="text-small text-muted">Runs author HTML away from panel cookies</span></div>
								</div>
								<figcaption class="mt-4 max-w-measure text-small text-muted"><strong class="text-ink">Public:</strong> page copy, author HTML/CSS and opted-in widgets. <strong class="ml-1 text-ink">Private:</strong> secrets, console, events, command analytics, people and deployments.</figcaption>
							</figure>
						{:else if section.id === 'widgets'}
							<div class="mt-6 grid divide-y divide-rule-soft border-y border-rule-soft sm:grid-cols-3 sm:divide-x sm:divide-y-0">
								<div class="py-4 sm:pr-4"><p class="text-small text-muted">Gateway latency</p><p class="mt-2 text-3xl font-semibold">42 <small class="text-small text-muted">ms</small></p><div class="mt-3 flex h-8 items-end gap-1">{#each [35,52,41,68,55,76,62,84] as h}<i class="flex-1 bg-action/65" style={`height:${h}%`}></i>{/each}</div></div>
								<div class="py-4 sm:px-4"><p class="text-small text-muted">Discord gateway</p><p class="mt-3 flex items-center gap-2 font-semibold"><span class="size-2 rounded-pill bg-run"></span>Connected</p><p class="mt-5 text-small text-muted">Updated 8 seconds ago</p></div>
								<div class="py-4 sm:pl-4"><p class="text-small text-muted">Queue</p><p class="mt-2 text-3xl font-semibold">68%</p><div class="mt-3 h-2 overflow-hidden rounded-pill bg-paper-2"><div class="h-full w-[68%] bg-action"></div></div></div>
							</div>
							<div class="mt-4 grid grid-cols-[minmax(0,1fr)] gap-3 lg:grid-cols-2"><div><p class="mb-1 text-small font-medium">Telemetry payload</p><pre class="max-h-72 overflow-auto rounded-tile bg-term p-4 font-mono text-[12px] leading-5 text-term-ink">{'{"widgets":[{"key":"latency","kind":"line","title":"Gateway latency","group":"Operations","span":2,"ttl_seconds":120,"data":{"unit":"ms","points":[{"label":"now","value":42}]}}]}'}</pre></div><div><p class="mb-1 text-small font-medium">Public-page CSS hook</p><pre class="max-h-72 overflow-auto rounded-tile bg-term p-4 font-mono text-[12px] leading-5 text-term-ink">{'[data-widget="latency"] {\n  grid-column: span 2;\n  border-color: var(--accent);\n}\n\n.kind-metric .metric {\n  font-variant-numeric: tabular-nums;\n}'}</pre></div></div>
						{:else if section.id === 'workspace-limits'}
							<div class="mt-6"><LimitsLegend note={false} /></div>
						{:else if section.id === 'security'}
							<div class="mt-6 grid gap-x-8 gap-y-5 border-t border-rule-soft pt-5 sm:grid-cols-2"><div><strong class="flex items-center gap-2 text-run"><Icon name="shield" size={15} />Enforced now</strong><p class="mt-1.5 text-small leading-6">App authorization, separate Sites origin, non-root containers, read-only runtime, capability drops and resource limits.</p></div><div><strong class="flex items-center gap-2 text-warn"><Icon name="alert" size={15} />Host controls still required</strong><p class="mt-1.5 text-small leading-6">Egress policy, disk quotas, IO and bandwidth need kernel, filesystem or network enforcement outside stored configuration.</p></div></div>
						{/if}
					</div>
				</section>
			{:else}
				<div class="rounded-card border border-rule-soft bg-panel p-10 text-center"><Icon name="search" size={24} class="mx-auto text-muted" /><h2 class="mt-3 text-title font-semibold">No matching documentation</h2><p class="mt-1 text-muted">Try a shorter search term or a feature name.</p></div>
			{/each}
		</main>
	</div>
</div>
